package ru.ryadom.calendar;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import org.junit.runner.RunWith;import org.json.*;import java.time.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class WidgetScrollTest {
 @Test public void separateCardsScrollAndUnchangedSyncKeepsTimeline()throws Exception{
  assertTrue(Build.HARDWARE.equals("ranchu")||Build.HARDWARE.equals("goldfish"));Instrumentation ins=InstrumentationRegistry.getInstrumentation();Context c=ins.getTargetContext();LocalDate day=LocalDate.now(Event.ZONE);long midnight=day.atStartOfDay(Event.ZONE).toInstant().toEpochMilli();JSONArray events=new JSONArray();
  for(int i=0;i<18;i++){Event e=new Event();e.id="scroll-"+i;e.source="scroll-fixture";e.calendar="main";e.title="Встреча "+(i+1);e.start=midnight+(540+i*35)*60000L;e.end=e.start+30*60000L;events.put(e.json());}
  java.util.List<Event> scaleEvents=new java.util.ArrayList<>();for(int i=0;i<events.length();i++)scaleEvents.add(Event.from(events.getJSONObject(i)));MainActivity.TimelineScale scale=new MainActivity.TimelineScale(MainActivity.blocks(scaleEvents,midnight),4f/3f);assertEquals(40f,scale.y(570)-scale.y(540),0.01f);assertEquals(1f,scale.y(575)-scale.y(570),0.01f);assertEquals(80f,scale.y(1320)-scale.y(1260),0.01f);
  Store.edit(c,d->{d.put("accounts",new JSONArray().put(new JSONObject().put("id","scroll-fixture").put("type","device").put("active",false)));d.put("events",events);d.put("hidden",new JSONObject());d.put("calendarStyles",new JSONObject());d.put("statuses",new JSONObject().put("scroll-fixture",new JSONObject().put("success",System.currentTimeMillis()).put("rangeStart",midnight).put("rangeEnd",midnight+86400000).put("calendars",new JSONObject().put("main","Тестовый"))));});
  MainActivity a=(MainActivity)ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));ins.waitForIdleSync();Thread.sleep(300);
  View[] root={null};ScrollView[] scroll={null};int[] position={0};ins.runOnMainSync(()->{a.handler.removeCallbacks(a.ticking);root[0]=a.root;scroll[0]=a.scroll;a.scroll.scrollTo(0,a.dp(600*a.minuteHeight));position[0]=a.scroll.getScrollY();assertEquals(40f*Math.max(1f,c.getResources().getConfiguration().fontScale),30*a.minuteHeight,0.01f);View title=new CalendarStyleTest().find(a.root,"Встреча 4");assertNotNull(title);assertTrue(title.getBottom()<=((View)title.getParent()).getHeight());});
  for(int i=0;i<4;i++){Store.edit(c,d->Store.object(d,"statuses").getJSONObject("scroll-fixture").put("success",System.currentTimeMillis()));c.sendBroadcast(new Intent(Sync.UPDATED).setPackage(c.getPackageName()));Thread.sleep(160);}
  ins.runOnMainSync(()->{assertSame(root[0],a.root);assertSame(scroll[0],a.scroll);assertEquals(position[0],a.scroll.getScrollY());});
  Store.edit(c,d->Store.array(d,"events").getJSONObject(2).put("title","Обновлённая встреча"));ins.runOnMainSync(a::refreshFromSync);ins.waitForIdleSync();Thread.sleep(200);ins.runOnMainSync(()->{assertNotSame(root[0],a.root);assertEquals(position[0],a.scroll.getScrollY());assertNotNull(new CalendarStyleTest().find(a.root,"Обновлённая встреча"));});new UiTest().screenshot(ins,"day-stable-scroll");
  AppWidgetManager manager=AppWidgetManager.getInstance(c);AppWidgetHost host=new AppWidgetHost(c,746);int id=host.allocateAppWidgetId();Bundle options=new Bundle();options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,420);options.putInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,420);options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,380);options.putInt(AppWidgetManager.OPTION_APPWIDGET_MAX_WIDTH,380);assertTrue(manager.bindAppWidgetIdIfAllowed(id,new ComponentName(c,TodayWidget.class),options));AppWidgetHostView[] widget={null};
  try{
   ins.runOnMainSync(()->{host.startListening();widget[0]=host.createView(a,id,manager.getAppWidgetInfo(id));FrameLayout frame=new FrameLayout(a);frame.setPadding(0,a.dp(35),0,0);frame.addView(widget[0],new FrameLayout.LayoutParams(-1,a.dp(420)));a.setContentView(frame);TodayWidget.refresh(c);});ins.waitForIdleSync();Thread.sleep(500);
   ListView[] list={null};ins.runOnMainSync(()->{list[0]=widget[0].findViewById(R.id.widget_events);assertNotNull(list[0]);assertTrue(list[0].getCount()>=18);assertTrue(list[0].canScrollVertically(1));list[0].setSelection(list[0].getCount()-2);});ins.waitForIdleSync();Thread.sleep(250);new UiTest().screenshot(ins,"widget-scroll-bottom");
   ins.runOnMainSync(()->{assertNotNull(new CalendarStyleTest().find(widget[0],"Встреча 18"));assertNull(new CalendarStyleTest().find(widget[0],"открыть день"));View title=new CalendarStyleTest().find(widget[0],"Встреча 18");View row=title;while(row.getId()!=R.id.row_root)row=(View)row.getParent();assertTrue(list[0].performItemClick((View)row.getParent(),list[0].getPositionForView(row),list[0].getItemIdAtPosition(list[0].getPositionForView(row))));});ins.waitForIdleSync();Thread.sleep(400);assertEquals("scroll-fixture|scroll-17",a.getIntent().getStringExtra("event"));new UiTest().screenshot(ins,"widget-scroll-event");ins.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);
  }finally{ins.runOnMainSync(host::stopListening);host.deleteAppWidgetId(id);ins.runOnMainSync(a::finish);}
 }
}
